<?php
if($path==='/face/status'&&$method==='GET'){role();try{$r=engine(['action'=>'test']);send(['status'=>'online','engine'=>$r,'timestamp'=>gmdate('c')]);}catch(ApiError $e){send(['status'=>'offline','engine'=>['status'=>'unavailable','yunet_loaded'=>false,'sface_loaded'=>false,'message'=>$e->getMessage()],'timestamp'=>gmdate('c')]);}}
if($path==='/face/validate-photo'&&$method==='POST'){role('ADMIN');need($body,['image_data']);photoBytes($body['image_data']);$r=engine(['action'=>'enroll','image'=>$body['image_data'],'min_quality'=>settings()['min_face_quality']]);if(empty($r['success']))send(['valid'=>false,'error'=>$r['message']??'Unable to validate this face.','error_code'=>$r['error_code']??'LOW_QUALITY']);send(['valid'=>true,'message'=>$r['message'],'quality_score'=>$r['quality_score']??null,'box'=>$r['box']??null,'metrics'=>$r['metrics']??null]);}
if($path==='/face/enroll'&&$method==='POST'){
 $u=role('ADMIN');need($body,['student_id','image_data']);if(empty($body['consent_granted']))fail('Student consent is required for enrollment.');$st=student($body['student_id']);if(!$st['is_active'])fail('Reactivate the student before enrolling a face.');photoBytes($body['image_data']);$r=engine(['action'=>'enroll','image'=>$body['image_data'],'min_quality'=>settings()['min_face_quality']]);if(empty($r['success'])||empty($r['embedding']))fail($r['message']??'Face enrollment failed.');$url=savePhoto($body['image_data']);transaction(function()use($u,$st,$r,$url){updateRow('students',$st['id'],['photo_url'=>$url]);$old=one('SELECT id,photo_count FROM face_enrollments WHERE student_id=?',[$st['id']]);$d=['photo_count'=>($old['photo_count']??0)+1,'encrypted_embedding'=>json_encode($r['embedding']),'face_embedding'=>json_encode($r['embedding']),'face_image_reference'=>$url,'face_quality'=>$r['quality_score']??1,'status'=>'ENROLLED','enrolled_by'=>$u['id'],'updated_at'=>gmdate('Y-m-d H:i:s')];if($old)updateRow('face_enrollments',$old['id'],$d);else insertRow('face_enrollments',['id'=>uid(),'student_id'=>$st['id'],...$d]);$consent=one('SELECT id FROM biometric_consents WHERE student_id=?',[$st['id']]);$d=['consent_granted'=>1,'signed_at'=>gmdate('Y-m-d H:i:s'),'ip_address'=>$_SERVER['REMOTE_ADDR']??null];if($consent)updateRow('biometric_consents',$consent['id'],$d);else insertRow('biometric_consents',['id'=>uid(),'student_id'=>$st['id'],...$d]);logBio($old?'REPLACE':'ENROLL',$st['id'],'Face enrolled for '.$st['full_name']);});send(['success'=>true,'message'=>'Face successfully enrolled.','photo_url'=>$url,'student'=>['id'=>$st['id'],'roll_no'=>$st['roll_no'],'full_name'=>$st['full_name'],'photo_url'=>$url,'class'=>$st['division_name'],'department'=>$st['department_name'],'face_status'=>'Enrolled','quality_score'=>$r['quality_score']??null],'box'=>$r['box']??null]);
}
if(preg_match('#^/face/(remove-photo|enrollment)/([^/]+)$#',$path,$m)&&(($m[1]==='remove-photo'&&$method==='POST')||($m[1]==='enrollment'&&$method==='DELETE'))){role('ADMIN');$st=student(urldecode($m[2]));transaction(function()use($m,$st){if($m[1]==='remove-photo'){updateRow('students',$st['id'],['photo_url'=>null]);query("UPDATE face_enrollments SET status='REVOKED',updated_at=UTC_TIMESTAMP() WHERE student_id=?",[$st['id']]);}else query('DELETE FROM face_enrollments WHERE student_id=?',[$st['id']]);logBio('DELETE',$st['id'],'Face enrollment disabled for '.$st['full_name']);});send(['success'=>true,'message'=>'Face enrollment removed.']);}
if($path==='/face/enrolled-students'&&$method==='GET'){role('ADMIN');$list=[];foreach(studentRows($q) as $st){$fe=one('SELECT id enrollment_id,face_quality,enrolled_at,updated_at,status face_status,(face_embedding IS NOT NULL) has_embedding FROM face_enrollments WHERE student_id=?',[$st['id']])??['face_status'=>'PENDING','has_embedding'=>0,'enrollment_id'=>null,'face_quality'=>null,'enrolled_at'=>null,'updated_at'=>null];$item=[...$st,'student_id'=>$st['id'],'class_name'=>$st['division_name'],...$fe];if(empty($q['status'])||$q['status']===$item['face_status'])$list[]=$item;}$enrolled=count(array_filter($list,fn($s)=>$s['face_status']==='ENROLLED'&&$s['has_embedding']));send(['total'=>count($list),'enrolledCount'=>$enrolled,'pendingCount'=>count($list)-$enrolled,'students'=>$list]);}
if($path==='/face/scan-classroom'&&$method==='POST'){role();need($body,['division_id','image_data']);divisionAccess($body['division_id']);photoBytes($body['image_data']);$students=rows("SELECT s.id student_id,s.roll_no,s.full_name,s.photo_url,CASE WHEN fe.status='ENROLLED' AND bc.consent_granted=1 THEN fe.face_embedding ELSE NULL END face_embedding FROM students s LEFT JOIN face_enrollments fe ON fe.student_id=s.id LEFT JOIN biometric_consents bc ON bc.student_id=s.id WHERE s.is_active=1 AND s.division_id=? ORDER BY s.roll_no",[$body['division_id']]);if(!$students)fail('No active students in this division.');$s=settings();$r=engine(['action'=>'scan','image'=>$body['image_data'],'enrolled'=>$students,'threshold'=>(float)$s['face_match_threshold'],'min_quality'=>(float)$s['min_face_quality'],'duplicate_protection'=>(bool)$s['duplicate_protection']]);if(empty($r['success']))fail($r['message']??'Classroom scan failed.');send([...$r,'threshold'=>(float)$s['face_match_threshold'],'enrolled_in_division'=>count($students),'faces_enrolled_count'=>count(array_filter($students,fn($s)=>!empty($s['face_embedding'])))]);}
if($path==='/face/confirm-attendance'&&$method==='POST'){role();send(transaction(fn()=>saveAttendance($body,'FACE_RECOGNITION')),201);}
if($path==='/face/history'&&$method==='GET'){role();send(['sessions'=>sessionRows($q,true)]);}
if($path==='/face/audit-logs'&&$method==='GET'){role('ADMIN');$sql='SELECT bal.*,u.full_name user_name,u.role user_role,s.full_name student_name,s.roll_no student_roll FROM biometric_audit_logs bal JOIN users u ON u.id=bal.user_id LEFT JOIN students s ON s.id=bal.student_id WHERE 1=1';$p=[];filterSql($sql,$p,['action'=>'bal.action','student_id'=>'bal.student_id'],$q);$limit=min(500,max(1,(int)($q['limit']??100)));send(['logs'=>rows($sql.' ORDER BY bal.timestamp DESC LIMIT '.$limit,$p)]);}
